import React from 'react';

const PestMotion = () => (
  <div className="pest-motion" aria-hidden="true">
    <span className="pest pest-termite">&#x1F41C;</span>
    <span className="pest pest-roach">&#x1F41E;</span>
    <span className="pest pest-ant">&#x1F41C;</span>
  </div>
);

export default PestMotion;
